CREATE VIEW v196361 AS SELECT ST_OVERLAPS(ST_GEOMETRYFROMTEXT('geometrycollection(polygon((0 0, 2 0, 2 1, 0 1, 0 0)))'), ST_GEOMETRYFROMTEXT('geometrycollection(polygon((1 0, 3 0, 3 1, 1 1, 1 0)))')), ST_SRID(ST_LINESTRINGFROMWKB(@wkb_ls, 4294967296)), ST_ASTEXT(ST_VALIDATE(ST_GEOMFROMTEXT('POLYGON((0 0, 10 0, 10 10, 0 10, 0 0))'))), SUM(LEAST(x8.v195559, x8.v195559)), SUM(x8.v195560), SUM(CASE WHEN x8.v195558 IS NULL THEN 0.00 ELSE x8.v195558 END), SUM(DISTINCT x8.v195558) FROM v195557 AS x8 GROUP BY x8.v195560 COLLATE utf8mb3_lithuanian_ci